import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2";

type Json = Record<string, unknown>;

const SESSION_TTL_MS = 12 * 60 * 60_000;
const REGISTRATION_SKEW_MS = 2 * 60_000;
const ONLINE_WINDOW_MS = 90_000;
const GATEWAY_WAIT_MS = 25_000;
const GATEWAY_POLL_MS = 400;

const TOOLS: Record<string, { scopes: string[]; mutating: boolean }> = {
  "bridge.handshake": { scopes: ["terminal:open"], mutating: false },
  "git.status": { scopes: ["git:read"], mutating: false },
  "metrics.read": { scopes: ["metrics:read"], mutating: false },
  "proc.list": { scopes: ["proc:list"], mutating: false },
  "logs.read": { scopes: ["logs:read"], mutating: false },
  "fs.list": { scopes: ["fs:read"], mutating: false },
  "fs.read": { scopes: ["fs:read"], mutating: false },
};

function json(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
      "x-content-type-options": "nosniff",
    },
  });
}

function serviceKey(): string {
  const modern = Deno.env.get("SUPABASE_SECRET_KEYS");
  if (modern) {
    try {
      const parsed = JSON.parse(modern) as Record<string, string>;
      if (parsed.default) return parsed.default;
    } catch {}
  }
  const legacy = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!legacy) throw new Error("service-key-unavailable");
  return legacy;
}

const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  serviceKey(),
  {
    auth: {
      persistSession: false,
      autoRefreshToken: false,
      detectSessionInUrl: false,
    },
  },
);

function base64UrlBytes(value: string): Uint8Array {
  const normalized = value.replace(/-/g, "+").replace(/_/g, "/");
  const padded = normalized + "=".repeat((4 - (normalized.length % 4)) % 4);
  const raw = atob(padded);
  return Uint8Array.from(raw, (char) => char.charCodeAt(0));
}

function pemDer(pem: string): Uint8Array {
  const body = pem
    .replace(/-----BEGIN [^-]+-----/g, "")
    .replace(/-----END [^-]+-----/g, "")
    .replace(/\s+/g, "");
  return Uint8Array.from(atob(body), (char) => char.charCodeAt(0));
}

function toHex(bytes: Uint8Array): string {
  return Array.from(bytes, (value) => value.toString(16).padStart(2, "0")).join("");
}

async function sha256Hex(value: string | Uint8Array): Promise<string> {
  const bytes = typeof value === "string" ? new TextEncoder().encode(value) : value;
  return toHex(new Uint8Array(await crypto.subtle.digest("SHA-256", bytes)));
}

async function bridgeFingerprint(publicKeyPem: string): Promise<string | null> {
  try {
    const der = pemDer(publicKeyPem);
    if (der.byteLength < 32) return null;
    return await sha256Hex(der.slice(der.byteLength - 32));
  } catch {
    return null;
  }
}

async function verifyBridgeSignature(
  publicKeyPem: string,
  payload: string,
  signature: string,
): Promise<boolean> {
  try {
    const key = await crypto.subtle.importKey(
      "spki",
      pemDer(publicKeyPem),
      { name: "Ed25519" },
      false,
      ["verify"],
    );
    return await crypto.subtle.verify(
      { name: "Ed25519" },
      key,
      base64UrlBytes(signature),
      new TextEncoder().encode(payload),
    );
  } catch {
    return false;
  }
}

function randomToken(bytes = 32): string {
  const value = new Uint8Array(bytes);
  crypto.getRandomValues(value);
  let binary = "";
  for (const byte of value) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function bearer(request: Request): string {
  const header = request.headers.get("authorization") ?? "";
  const match = /^Bearer\s+([A-Za-z0-9_-]{20,512})$/i.exec(header);
  return match?.[1] ?? "";
}

function validObject(value: unknown): value is Json {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function validateArgs(tool: string, raw: unknown):
  | { ok: true; args: Json }
  | { ok: false; error: string } {
  const args = validObject(raw) ? raw : {};

  if (["bridge.handshake", "git.status", "metrics.read", "proc.list"].includes(tool)) {
    return Object.keys(args).length === 0
      ? { ok: true, args: {} }
      : { ok: false, error: "unexpected-arguments" };
  }

  if (tool === "logs.read") {
    const name = typeof args.name === "string" ? args.name.trim() : "";
    if (!/^[A-Za-z0-9._-]{1,64}$/.test(name)) {
      return { ok: false, error: "invalid-process-name" };
    }
    const since = Number.isInteger(args.since) && Number(args.since) >= 0
      ? Number(args.since)
      : 0;
    const limit = Number.isInteger(args.limit)
      ? Math.max(1, Math.min(500, Number(args.limit)))
      : 200;
    return { ok: true, args: { name, since, limit } };
  }

  if (tool === "fs.list" || tool === "fs.read") {
    const path = typeof args.path === "string" ? args.path.trim() : "";
    if (!path || path.length > 4096 || path.includes("\0")) {
      return { ok: false, error: "invalid-path" };
    }
    return { ok: true, args: { path } };
  }

  return { ok: false, error: "tool-not-allowlisted" };
}

async function parseJson(request: Request): Promise<Json | null> {
  try {
    const parsed = await request.json();
    return validObject(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

async function authenticateMachine(request: Request) {
  const token = bearer(request);
  if (!token) return null;

  const tokenHash = await sha256Hex(token);
  const { data: session } = await supabase
    .from("knoux_bridge_sessions")
    .select("id,machine_id,owner_id,expires_at,revoked_at")
    .eq("token_hash", tokenHash)
    .maybeSingle();

  if (!session || session.revoked_at || Date.parse(session.expires_at) <= Date.now()) {
    return null;
  }

  const { data: machine } = await supabase
    .from("knoux_bridge_machines")
    .select("id,owner_id,bridge_id,fingerprint,status")
    .eq("id", session.machine_id)
    .maybeSingle();

  if (!machine || machine.status === "revoked" || machine.owner_id !== session.owner_id) {
    return null;
  }

  return { session, machine };
}

async function authenticateGateway(request: Request) {
  const token = bearer(request);
  if (!token) return null;

  const tokenHash = await sha256Hex(token);
  const now = new Date().toISOString();

  const { data: gateway } = await supabase
    .from("knoux_bridge_gateway_tokens")
    .select("id,name,bridge_id,active,expires_at")
    .eq("token_hash", tokenHash)
    .eq("active", true)
    .maybeSingle();

  if (!gateway) return null;
  if (gateway.expires_at && Date.parse(gateway.expires_at) <= Date.now()) return null;

  await supabase
    .from("knoux_bridge_gateway_tokens")
    .update({ last_used_at: now })
    .eq("id", gateway.id);

  return gateway;
}

async function register(request: Request): Promise<Response> {
  const body = await parseJson(request);
  if (!body || typeof body.payload !== "string" || typeof body.signature !== "string") {
    return json(400, { error: "invalid-envelope" });
  }
  if (body.payload.length > 64_000 || body.signature.length > 1_000) {
    return json(400, { error: "invalid-envelope" });
  }

  let payload: Json;
  try {
    payload = JSON.parse(body.payload) as Json;
  } catch {
    return json(400, { error: "invalid-payload" });
  }

  const bridgeId = typeof payload.bridgeId === "string" ? payload.bridgeId : "";
  const fingerprint = typeof payload.fingerprint === "string" ? payload.fingerprint : "";
  const publicKey = typeof payload.publicKey === "string" ? payload.publicKey : "";
  const nonce = typeof payload.nonce === "string" ? payload.nonce : "";
  const timestamp = typeof payload.timestamp === "string" ? payload.timestamp : "";
  const hostname = typeof payload.hostname === "string" ? payload.hostname : "";
  const platform = typeof payload.platform === "string" ? payload.platform : "";
  const arch = typeof payload.arch === "string" ? payload.arch : "";
  const version = typeof payload.version === "string" ? payload.version : "";
  const capabilities = validObject(payload.capabilities) ? payload.capabilities : null;

  if (
    !/^[0-9a-f]{16,64}$/.test(bridgeId) ||
    !/^[0-9a-f]{64}$/.test(fingerprint) ||
    !/^[A-Za-z0-9_-]{16,128}$/.test(nonce) ||
    !publicKey || !hostname || !platform || !arch || !version || !capabilities
  ) {
    return json(400, { error: "invalid-payload" });
  }

  if (bridgeId !== fingerprint.slice(0, 16)) {
    return json(401, { error: "bridge-id-mismatch" });
  }

  const measuredAt = Date.parse(timestamp);
  if (!Number.isFinite(measuredAt) || Math.abs(Date.now() - measuredAt) > REGISTRATION_SKEW_MS) {
    return json(401, { error: "stale-registration" });
  }

  const measuredFingerprint = await bridgeFingerprint(publicKey);
  if (!measuredFingerprint || measuredFingerprint !== fingerprint) {
    return json(401, { error: "public-key-mismatch" });
  }

  if (!await verifyBridgeSignature(publicKey, body.payload, body.signature)) {
    return json(401, { error: "invalid-signature" });
  }

  const now = new Date();
  const nowIso = now.toISOString();

  const { data: existing, error: lookupError } = await supabase
    .from("knoux_bridge_machines")
    .select("id,owner_id,bridge_id,fingerprint,public_key,status")
    .eq("bridge_id", bridgeId)
    .maybeSingle();

  if (lookupError) return json(503, { error: "machine-lookup-failed" });

  let machine: { id: string; owner_id: string; bridge_id: string };

  if (existing) {
    if (
      existing.fingerprint !== fingerprint ||
      existing.public_key !== publicKey ||
      existing.status === "revoked"
    ) {
      return json(403, { error: "machine-identity-rejected" });
    }
    machine = { id: existing.id, owner_id: existing.owner_id, bridge_id: existing.bridge_id };
  } else {
    const enrollmentToken = typeof payload.enrollmentToken === "string"
      ? payload.enrollmentToken.trim()
      : "";

    if (!/^[A-Za-z0-9_-]{20,128}$/.test(enrollmentToken)) {
      return json(403, { error: "enrollment-required" });
    }

    const { data: enrolled, error: enrollmentError } = await supabase.rpc(
      "knoux_bridge_enroll_machine",
      {
        p_token_hash: await sha256Hex(enrollmentToken),
        p_bridge_id: bridgeId,
        p_fingerprint: fingerprint,
        p_public_key: publicKey,
        p_hostname: hostname.slice(0, 255),
        p_platform: platform.slice(0, 64),
        p_arch: arch.slice(0, 64),
        p_bridge_version: version.slice(0, 64),
        p_capabilities: capabilities,
      },
    );

    const row = Array.isArray(enrolled) ? enrolled[0] : null;
    if (enrollmentError || !row) {
      return json(403, { error: "enrollment-invalid-or-expired" });
    }

    machine = { id: row.id, owner_id: row.owner_id, bridge_id: row.bridge_id };
  }

  const { error: nonceError } = await supabase
    .from("knoux_bridge_registration_nonces")
    .insert({
      nonce,
      machine_id: machine.id,
      expires_at: new Date(now.getTime() + 10 * 60_000).toISOString(),
    });

  if (nonceError) return json(409, { error: "registration-replay" });

  if (existing) {
    const { error: refreshError } = await supabase
      .from("knoux_bridge_machines")
      .update({
        hostname: hostname.slice(0, 255),
        platform: platform.slice(0, 64),
        arch: arch.slice(0, 64),
        bridge_version: version.slice(0, 64),
        capabilities,
        status: "online",
        last_seen_at: nowIso,
        updated_at: nowIso,
      })
      .eq("id", machine.id);

    if (refreshError) return json(503, { error: "machine-refresh-failed" });
  }

  await supabase
    .from("knoux_bridge_sessions")
    .update({ revoked_at: nowIso })
    .eq("machine_id", machine.id)
    .is("revoked_at", null);

  const sessionToken = randomToken(32);
  const expiresAt = new Date(now.getTime() + SESSION_TTL_MS).toISOString();

  const { data: session, error: sessionError } = await supabase
    .from("knoux_bridge_sessions")
    .insert({
      machine_id: machine.id,
      owner_id: machine.owner_id,
      token_hash: await sha256Hex(sessionToken),
      expires_at: expiresAt,
      last_seen_at: nowIso,
    })
    .select("id")
    .single();

  if (sessionError || !session) return json(503, { error: "session-create-failed" });

  await supabase.from("knoux_bridge_events").insert({
    owner_id: machine.owner_id,
    machine_id: machine.id,
    session_id: session.id,
    event: existing ? "machine.reconnected" : "machine.enrolled",
    detail: { bridgeId, hostname, platform, version },
  });

  return json(200, {
    ok: true,
    machineId: machine.id,
    sessionId: session.id,
    sessionToken,
    expiresAt,
    heartbeatIntervalMs: 30_000,
    idlePollMs: 2_000,
  });
}

async function heartbeat(request: Request): Promise<Response> {
  const auth = await authenticateMachine(request);
  if (!auth) return json(401, { error: "machine-unauthorized" });

  const body = await parseJson(request) ?? {};
  const now = new Date().toISOString();
  const update: Json = { status: "online", last_seen_at: now, updated_at: now };

  if (typeof body.version === "string" && body.version.length <= 64) {
    update.bridge_version = body.version;
  }
  if (validObject(body.capabilities)) update.capabilities = body.capabilities;

  await Promise.all([
    supabase.from("knoux_bridge_machines").update(update).eq("id", auth.machine.id),
    supabase.from("knoux_bridge_sessions").update({ last_seen_at: now }).eq("id", auth.session.id),
  ]);

  return json(200, {
    ok: true,
    machineId: auth.machine.id,
    serverTime: now,
    sessionExpiresAt: auth.session.expires_at,
  });
}

async function poll(request: Request): Promise<Response> {
  const auth = await authenticateMachine(request);
  if (!auth) return json(401, { error: "machine-unauthorized" });

  const now = new Date().toISOString();
  await Promise.all([
    supabase.from("knoux_bridge_machines").update({
      status: "online", last_seen_at: now, updated_at: now,
    }).eq("id", auth.machine.id),
    supabase.from("knoux_bridge_sessions").update({ last_seen_at: now }).eq("id", auth.session.id),
  ]);

  const { data, error } = await supabase.rpc("knoux_bridge_claim_job", {
    p_machine_id: auth.machine.id,
    p_session_id: auth.session.id,
  });

  if (error) return json(503, { error: "job-claim-failed" });

  const job = Array.isArray(data) ? data[0] : null;
  if (!job) return new Response(null, { status: 204 });

  const spec = TOOLS[job.tool];
  if (!spec || spec.mutating) {
    await supabase.from("knoux_bridge_jobs").update({
      status: "failed",
      completed_at: now,
      error: "Tool is not allowlisted by the KNOuX Store control plane.",
    }).eq("id", job.id);
    return json(409, { error: "job-not-allowlisted" });
  }

  await supabase.from("knoux_bridge_events").insert({
    owner_id: auth.session.owner_id,
    machine_id: auth.machine.id,
    session_id: auth.session.id,
    job_id: job.id,
    event: "job.claimed",
    detail: { tool: job.tool },
  });

  return json(200, {
    ok: true,
    job: {
      id: job.id,
      tool: job.tool,
      args: job.args ?? {},
      expiresAt: job.expires_at,
    },
  });
}

async function result(request: Request): Promise<Response> {
  const auth = await authenticateMachine(request);
  if (!auth) return json(401, { error: "machine-unauthorized" });

  const body = await parseJson(request);
  if (!body) return json(400, { error: "invalid-body" });

  const jobId = typeof body.jobId === "string" ? body.jobId : "";
  if (!/^[0-9a-f-]{36}$/i.test(jobId)) return json(400, { error: "invalid-job-id" });

  const ok = body.ok === true;
  const durationMs = Number.isFinite(body.durationMs) && Number(body.durationMs) >= 0
    ? Math.min(Number(body.durationMs), 86_400_000)
    : null;
  const errorText = typeof body.error === "string" ? body.error.slice(0, 2_000) : null;

  const { data: job } = await supabase
    .from("knoux_bridge_jobs")
    .select("id,owner_id,machine_id,status")
    .eq("id", jobId)
    .eq("machine_id", auth.machine.id)
    .maybeSingle();

  if (!job) return json(404, { error: "job-not-found" });
  if (!["claimed", "running"].includes(job.status)) {
    return json(409, { error: "job-not-claimable" });
  }

  const completedAt = new Date().toISOString();
  const update: Json = {
    status: ok ? "succeeded" : "failed",
    completed_at: completedAt,
    result: ok ? (body.result ?? null) : null,
    error: ok ? null : (errorText ?? "The local bridge reported a failure."),
    duration_ms: durationMs,
  };
  if (job.status === "claimed") update.started_at = completedAt;

  await supabase.from("knoux_bridge_jobs").update(update).eq("id", job.id);
  await supabase.from("knoux_bridge_events").insert({
    owner_id: auth.session.owner_id,
    machine_id: auth.machine.id,
    session_id: auth.session.id,
    job_id: job.id,
    event: ok ? "job.succeeded" : "job.failed",
    detail: { durationMs },
  });

  return json(200, { ok: true });
}

async function gatewayStatus(request: Request): Promise<Response> {
  const gateway = await authenticateGateway(request);
  if (!gateway) return json(401, { error: "gateway-unauthorized" });

  const { data: machine } = await supabase
    .from("knoux_bridge_machines")
    .select("id,bridge_id,hostname,platform,arch,bridge_version,capabilities,status,last_seen_at,registered_at")
    .eq("bridge_id", gateway.bridge_id)
    .maybeSingle();

  if (!machine) {
    return json(200, {
      ok: true,
      service: "knoux-store-bridge-control",
      local_machine_connected: false,
      machine: null,
      measuredAt: new Date().toISOString(),
    });
  }

  const ageMs = Math.max(0, Date.now() - Date.parse(machine.last_seen_at));
  const online = machine.status !== "revoked" && ageMs <= ONLINE_WINDOW_MS;

  return json(200, {
    ok: true,
    service: "knoux-store-bridge-control",
    local_machine_connected: online,
    machine: {
      id: machine.id,
      bridgeId: machine.bridge_id,
      hostname: machine.hostname,
      platform: machine.platform,
      arch: machine.arch,
      version: machine.bridge_version,
      capabilities: machine.capabilities,
      status: machine.status === "revoked" ? "revoked" : (online ? "online" : "offline"),
      lastSeenAt: machine.last_seen_at,
      lastSeenAgeMs: ageMs,
      registeredAt: machine.registered_at,
    },
    measuredAt: new Date().toISOString(),
  });
}

async function gatewayRun(request: Request): Promise<Response> {
  const gateway = await authenticateGateway(request);
  if (!gateway) return json(401, { error: "gateway-unauthorized" });

  const body = await parseJson(request);
  if (!body) return json(400, { error: "invalid-body" });

  const tool = typeof body.tool === "string" ? body.tool.trim() : "";
  const spec = TOOLS[tool];
  if (!spec || spec.mutating) return json(400, { error: "tool-not-allowlisted" });

  const validated = validateArgs(tool, body.args);
  if (!validated.ok) return json(400, { error: validated.error });

  const { data: machine } = await supabase
    .from("knoux_bridge_machines")
    .select("id,owner_id,bridge_id,status,last_seen_at")
    .eq("bridge_id", gateway.bridge_id)
    .maybeSingle();

  if (!machine) return json(404, { error: "machine-not-found" });

  const ageMs = Date.now() - Date.parse(machine.last_seen_at);
  if (machine.status === "revoked" || ageMs > ONLINE_WINDOW_MS) {
    return json(409, { error: "machine-offline" });
  }

  const { data: job, error: createError } = await supabase
    .from("knoux_bridge_jobs")
    .insert({
      owner_id: machine.owner_id,
      machine_id: machine.id,
      tool,
      args: validated.args,
      required_scopes: spec.scopes,
      mutating: false,
      idempotency_key: crypto.randomUUID(),
      expires_at: new Date(Date.now() + 5 * 60_000).toISOString(),
    })
    .select("id,status,created_at,expires_at")
    .single();

  if (createError || !job) return json(503, { error: "job-create-failed" });

  const deadline = Date.now() + GATEWAY_WAIT_MS;
  while (Date.now() < deadline) {
    const { data: current } = await supabase
      .from("knoux_bridge_jobs")
      .select("id,status,result,error,duration_ms,completed_at")
      .eq("id", job.id)
      .maybeSingle();

    if (current && ["succeeded", "failed", "cancelled", "expired"].includes(current.status)) {
      return json(current.status === "succeeded" ? 200 : 502, {
        ok: current.status === "succeeded",
        jobId: current.id,
        tool,
        status: current.status,
        result: current.result,
        error: current.error,
        durationMs: current.duration_ms,
        completedAt: current.completed_at,
      });
    }

    await new Promise((resolve) => setTimeout(resolve, GATEWAY_POLL_MS));
  }

  return json(504, {
    ok: false,
    error: "job-timeout",
    jobId: job.id,
    tool,
  });
}

Deno.serve(async (request: Request) => {
  if (request.method !== "POST") {
    return json(405, { error: "method-not-allowed" });
  }

  const parts = new URL(request.url).pathname.split("/").filter(Boolean);
  const action = parts.at(-1) ?? "";

  try {
    switch (action) {
      case "register":
        return await register(request);
      case "heartbeat":
        return await heartbeat(request);
      case "poll":
        return await poll(request);
      case "result":
        return await result(request);
      case "status":
        if (parts.at(-2) === "gateway") return await gatewayStatus(request);
        break;
      case "run":
        if (parts.at(-2) === "gateway") return await gatewayRun(request);
        break;
    }

    return json(404, { error: "not-found" });
  } catch (error) {
    console.error("knoux-bridge-control", error);
    return json(500, { error: "internal-error" });
  }
});

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")?.replace(/\/$/, "") ?? "";
const CONTROL_URL = `${SUPABASE_URL}/functions/v1/knoux-bridge-control`;
const PROTOCOL_VERSION = "2025-06-18";

type JsonRpcId = string | number | null;

const TOOLS = [
  {
    name: "gateway_status",
    description: "Return measured KNOuX Store local-machine connectivity and heartbeat state.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false },
  },
  {
    name: "machine_git_status",
    description: "Read the real Git status and recent commits from the enrolled KNOuX Store Windows machine.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false },
  },
  {
    name: "machine_metrics",
    description: "Read measured CPU, memory, disk, network and bridge process metrics from the enrolled machine.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false },
  },
  {
    name: "machine_processes",
    description: "List supervised KNOuX Store processes. Read-only.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false },
  },
  {
    name: "machine_list_files",
    description: "List files under the KNOuX Store bridge root. The local path policy remains authoritative.",
    inputSchema: {
      type: "object",
      properties: { path: { type: "string", default: "." } },
      additionalProperties: false,
    },
  },
  {
    name: "machine_read_file",
    description: "Read one file under the KNOuX Store bridge root. Read-only and root-confined.",
    inputSchema: {
      type: "object",
      properties: { path: { type: "string" } },
      required: ["path"],
      additionalProperties: false,
    },
  },
  {
    name: "machine_logs",
    description: "Read bounded output from one supervised KNOuX Store process.",
    inputSchema: {
      type: "object",
      properties: {
        name: { type: "string" },
        since: { type: "integer", minimum: 0, default: 0 },
        limit: { type: "integer", minimum: 1, maximum: 500, default: 200 },
      },
      required: ["name"],
      additionalProperties: false,
    },
  },
] as const;

function rpcResult(id: JsonRpcId, result: unknown, status = 200): Response {
  return new Response(JSON.stringify({ jsonrpc: "2.0", id, result }), {
    status,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
      "mcp-protocol-version": PROTOCOL_VERSION,
    },
  });
}

function rpcError(
  id: JsonRpcId,
  code: number,
  message: string,
  status = 200,
  data?: unknown,
): Response {
  return new Response(JSON.stringify({
    jsonrpc: "2.0",
    id,
    error: { code, message, ...(data === undefined ? {} : { data }) },
  }), {
    status,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
      "mcp-protocol-version": PROTOCOL_VERSION,
    },
  });
}

function textContent(value: unknown, isError = false) {
  return {
    content: [{
      type: "text",
      text: JSON.stringify(value, null, 2),
    }],
    isError,
  };
}

async function control(
  token: string,
  path: "gateway/status" | "gateway/run",
  body: Record<string, unknown>,
): Promise<{ ok: boolean; status: number; body: any }> {
  const response = await fetch(`${CONTROL_URL}/${path}`, {
    method: "POST",
    headers: {
      authorization: `Bearer ${token}`,
      "content-type": "application/json",
      accept: "application/json",
    },
    body: JSON.stringify(body),
  });

  let payload: any;
  try {
    payload = await response.json();
  } catch {
    payload = { error: "control-plane-non-json" };
  }

  return { ok: response.ok, status: response.status, body: payload };
}

function tokenFrom(req: Request): string | null {
  const match = /^Bearer\s+([A-Za-z0-9_-]{32,256})$/i.exec(
    req.headers.get("authorization") ?? "",
  );
  return match?.[1] ?? null;
}

function validPath(value: unknown): value is string {
  return typeof value === "string"
    && value.length > 0
    && value.length <= 4096
    && !value.includes("\0");
}

async function callTool(
  token: string,
  name: string,
  rawArgs: unknown,
): Promise<{ result: unknown; isError: boolean }> {
  const args = rawArgs && typeof rawArgs === "object" && !Array.isArray(rawArgs)
    ? rawArgs as Record<string, unknown>
    : {};

  if (name === "gateway_status") {
    const out = await control(token, "gateway/status", {});
    return { result: out.body, isError: !out.ok };
  }

  let tool = "";
  let toolArgs: Record<string, unknown> = {};

  switch (name) {
    case "machine_git_status":
      tool = "git.status";
      break;
    case "machine_metrics":
      tool = "metrics.read";
      break;
    case "machine_processes":
      tool = "proc.list";
      break;
    case "machine_list_files": {
      const path = args.path ?? ".";
      if (!validPath(path)) {
        return { result: { error: "invalid-path" }, isError: true };
      }
      tool = "fs.list";
      toolArgs = { path };
      break;
    }
    case "machine_read_file": {
      if (!validPath(args.path)) {
        return { result: { error: "invalid-path" }, isError: true };
      }
      tool = "fs.read";
      toolArgs = { path: args.path };
      break;
    }
    case "machine_logs": {
      const processName = typeof args.name === "string" ? args.name.trim() : "";
      if (!/^[A-Za-z0-9._-]{1,64}$/.test(processName)) {
        return { result: { error: "invalid-process-name" }, isError: true };
      }
      const since = Number.isInteger(args.since) && Number(args.since) >= 0
        ? Number(args.since) : 0;
      const limit = Number.isInteger(args.limit)
        ? Math.max(1, Math.min(500, Number(args.limit)))
        : 200;
      tool = "logs.read";
      toolArgs = { name: processName, since, limit };
      break;
    }
    default:
      return { result: { error: "unknown-tool", name }, isError: true };
  }

  const out = await control(token, "gateway/run", { tool, args: toolArgs });
  return { result: out.body, isError: !out.ok };
}

Deno.serve(async (req: Request) => {
  const url = new URL(req.url);

  if (req.method === "GET" && url.pathname.endsWith("/health")) {
    return new Response(JSON.stringify({
      ok: true,
      service: "knoux-store-mcp-gateway",
      transport: "streamable-http-json",
      protocolVersion: PROTOCOL_VERSION,
      tools: TOOLS.length,
    }), {
      headers: {
        "content-type": "application/json; charset=utf-8",
        "cache-control": "no-store",
      },
    });
  }

  if (req.method !== "POST") {
    return new Response(null, { status: 405 });
  }

  const token = tokenFrom(req);
  if (!token) {
    return rpcError(null, -32001, "Unauthorized", 401);
  }

  let message: any;
  try {
    const text = await req.text();
    if (text.length > 256_000) {
      return rpcError(null, -32600, "Request too large", 413);
    }
    message = JSON.parse(text);
  } catch {
    return rpcError(null, -32700, "Parse error", 400);
  }

  if (!message || message.jsonrpc !== "2.0" || typeof message.method !== "string") {
    return rpcError(message?.id ?? null, -32600, "Invalid Request", 400);
  }

  const id: JsonRpcId = message.id ?? null;

  if (message.method === "notifications/initialized") {
    return new Response(null, { status: 202 });
  }

  if (message.method === "initialize") {
    const authCheck = await control(token, "gateway/status", {});
    if (!authCheck.ok) {
      return rpcError(id, -32001, "Unauthorized", 401);
    }

    return rpcResult(id, {
      protocolVersion: PROTOCOL_VERSION,
      capabilities: {
        tools: { listChanged: false },
      },
      serverInfo: {
        name: "KNOuX Store MCP Gateway",
        version: "1.0.0",
      },
      instructions:
        "Read-only KNOuX Store local-machine tools routed through the outbound KNOuX Bridge control plane.",
    });
  }

  if (message.method === "ping") {
    return rpcResult(id, {});
  }

  if (message.method === "tools/list") {
    const authCheck = await control(token, "gateway/status", {});
    if (!authCheck.ok) {
      return rpcError(id, -32001, "Unauthorized", 401);
    }
    return rpcResult(id, { tools: TOOLS });
  }

  if (message.method === "tools/call") {
    const params = message.params;
    if (!params || typeof params.name !== "string") {
      return rpcError(id, -32602, "Invalid params");
    }
    const called = await callTool(token, params.name, params.arguments);
    return rpcResult(id, textContent(called.result, called.isError));
  }

  return rpcError(id, -32601, "Method not found");
});

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2";

const ONLINE_WINDOW_MS = 90_000;
const JOB_TIMEOUT_MS = 25_000;
const POLL_INTERVAL_MS = 500;

const TOOL_SPECS: Record<string, { scopes: string[] }> = {
  "bridge.handshake": { scopes: ["terminal:open"] },
  "git.status": { scopes: ["git:read"] },
  "metrics.read": { scopes: ["metrics:read"] },
  "proc.list": { scopes: ["proc:list"] },
  "logs.read": { scopes: ["logs:read"] },
  "fs.list": { scopes: ["fs:read"] },
  "fs.read": { scopes: ["fs:read"] },
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store",
    },
  });
}

function getSecretKey(): string {
  const modern = Deno.env.get("SUPABASE_SECRET_KEYS");
  if (modern) {
    try {
      const parsed = JSON.parse(modern) as Record<string, string>;
      if (typeof parsed.default === "string" && parsed.default) return parsed.default;
      const first = Object.values(parsed).find((value) => typeof value === "string" && value);
      if (first) return first;
    } catch {
      // Fall through to the legacy server key.
    }
  }

  const legacy = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!legacy) throw new Error("Supabase server secret is unavailable.");
  return legacy;
}

const supabaseUrl = Deno.env.get("SUPABASE_URL");
if (!supabaseUrl) throw new Error("SUPABASE_URL is unavailable.");

const admin = createClient(supabaseUrl, getSecretKey(), {
  auth: {
    persistSession: false,
    autoRefreshToken: false,
    detectSessionInUrl: false,
  },
});

async function sha256Hex(value: string): Promise<string> {
  const bytes = new TextEncoder().encode(value);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest))
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

type GatewayAccess = {
  id: string;
  bridge_id: string;
  expires_at: string | null;
};

async function authenticateGateway(request: Request): Promise<GatewayAccess | null> {
  const token = request.headers.get("x-knoux-gateway-token")?.trim() ?? "";
  if (!/^[A-Za-z0-9_-]{40,256}$/.test(token)) return null;

  const tokenHash = await sha256Hex(token);
  const { data, error } = await admin
    .from("knoux_bridge_gateway_tokens")
    .select("id,bridge_id,expires_at,active")
    .eq("token_hash", tokenHash)
    .eq("active", true)
    .maybeSingle();

  if (error || !data) return null;
  if (data.expires_at && Date.parse(data.expires_at) <= Date.now()) return null;

  await admin
    .from("knoux_bridge_gateway_tokens")
    .update({ last_used_at: new Date().toISOString() })
    .eq("id", data.id);

  return {
    id: data.id,
    bridge_id: data.bridge_id,
    expires_at: data.expires_at,
  };
}

async function getMachine(bridgeId: string) {
  const { data, error } = await admin
    .from("knoux_bridge_machines")
    .select(
      "id,owner_id,bridge_id,hostname,platform,arch,bridge_version,capabilities,status,last_seen_at,registered_at",
    )
    .eq("bridge_id", bridgeId)
    .maybeSingle();

  if (error) throw new Error("Machine lookup failed.");
  return data;
}

function machineState(machine: Record<string, unknown> | null) {
  if (!machine) {
    return { online: false, ageMs: null as number | null };
  }

  const status = String(machine.status ?? "");
  const lastSeenAt = String(machine.last_seen_at ?? "");
  const measured = Date.parse(lastSeenAt);

  if (status === "revoked" || !Number.isFinite(measured)) {
    return { online: false, ageMs: null as number | null };
  }

  const ageMs = Math.max(0, Date.now() - measured);
  return {
    online: ageMs <= ONLINE_WINDOW_MS,
    ageMs,
  };
}

function validateArgs(
  tool: string,
  raw: unknown,
): { ok: true; args: Record<string, unknown> } | { ok: false; error: string } {
  const args =
    typeof raw === "object" && raw !== null && !Array.isArray(raw)
      ? (raw as Record<string, unknown>)
      : {};

  switch (tool) {
    case "bridge.handshake":
    case "git.status":
    case "metrics.read":
    case "proc.list":
      return Object.keys(args).length === 0
        ? { ok: true, args: {} }
        : { ok: false, error: tool + " does not accept arguments." };

    case "logs.read": {
      const name = typeof args.name === "string" ? args.name.trim() : "";
      if (!/^[A-Za-z0-9._-]{1,64}$/.test(name)) {
        return { ok: false, error: "logs.read requires a valid supervised process name." };
      }
      const since = Number.isInteger(args.since) && Number(args.since) >= 0
        ? Number(args.since)
        : 0;
      const limit = Number.isInteger(args.limit)
        ? Math.max(1, Math.min(500, Number(args.limit)))
        : 200;
      return { ok: true, args: { name, since, limit } };
    }

    case "fs.list":
    case "fs.read": {
      const path = typeof args.path === "string" ? args.path.trim() : "";
      if (!path || path.length > 4096 || path.includes("\0")) {
        return { ok: false, error: tool + " requires a valid path." };
      }
      return { ok: true, args: { path } };
    }

    default:
      return { ok: false, error: "Tool is not allowlisted." };
  }
}

async function gatewayStatus(access: GatewayAccess): Promise<Response> {
  const machine = await getMachine(access.bridge_id);
  const state = machineState(machine);

  return json({
    ok: true,
    service: "knoux-bridge-gateway-api",
    product: "KNOuX Store",
    mode: "OUTBOUND_CONTROL_PLANE",
    local_machine_connected: state.online,
    machine: machine
      ? {
          bridge_id: machine.bridge_id,
          hostname: machine.hostname,
          platform: machine.platform,
          arch: machine.arch,
          version: machine.bridge_version,
          status: machine.status === "revoked"
            ? "revoked"
            : state.online
              ? "online"
              : "offline",
          last_seen_at: machine.last_seen_at,
          last_seen_age_ms: state.ageMs,
          registered_at: machine.registered_at,
          capabilities: machine.capabilities ?? {},
        }
      : null,
    measured_at: new Date().toISOString(),
  });
}

async function gatewayTool(
  access: GatewayAccess,
  body: Record<string, unknown>,
): Promise<Response> {
  const tool = typeof body.tool === "string" ? body.tool.trim() : "";
  const spec = TOOL_SPECS[tool];
  if (!spec) return json({ ok: false, error: "tool-not-allowlisted" }, 400);

  const validated = validateArgs(tool, body.args);
  if (!validated.ok) {
    return json({ ok: false, error: "invalid-tool-args", message: validated.error }, 400);
  }

  const machine = await getMachine(access.bridge_id);
  if (!machine) return json({ ok: false, error: "machine-not-found" }, 404);

  const state = machineState(machine);
  if (!state.online) {
    return json({ ok: false, error: "machine-offline" }, 409);
  }

  const { data: job, error: insertError } = await admin
    .from("knoux_bridge_jobs")
    .insert({
      owner_id: machine.owner_id,
      machine_id: machine.id,
      tool,
      args: validated.args,
      required_scopes: spec.scopes,
      mutating: false,
      idempotency_key: "gateway-" + crypto.randomUUID(),
      expires_at: new Date(Date.now() + 5 * 60_000).toISOString(),
    })
    .select("id,status,created_at,expires_at")
    .single();

  if (insertError || !job) {
    return json({ ok: false, error: "job-create-failed" }, 503);
  }

  const deadline = Date.now() + JOB_TIMEOUT_MS;

  while (Date.now() < deadline) {
    const { data: current, error: readError } = await admin
      .from("knoux_bridge_jobs")
      .select("id,status,result,error,duration_ms,claimed_at,completed_at")
      .eq("id", job.id)
      .maybeSingle();

    if (readError) {
      return json({ ok: false, error: "job-read-failed", job_id: job.id }, 503);
    }

    if (current) {
      if (current.status === "succeeded") {
        return json({
          ok: true,
          job_id: job.id,
          tool,
          result: current.result,
          duration_ms: current.duration_ms,
          claimed_at: current.claimed_at,
          completed_at: current.completed_at,
        });
      }

      if (["failed", "cancelled", "expired"].includes(current.status)) {
        return json({
          ok: false,
          job_id: job.id,
          tool,
          status: current.status,
          error: current.error ?? "The local job did not succeed.",
          duration_ms: current.duration_ms,
          completed_at: current.completed_at,
        }, 502);
      }
    }

    await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
  }

  return json({
    ok: false,
    error: "job-timeout",
    job_id: job.id,
    tool,
  }, 504);
}

Deno.serve(async (request: Request) => {
  if (request.method !== "POST") {
    return json({ ok: false, error: "method-not-allowed" }, 405);
  }

  const access = await authenticateGateway(request);
  if (!access) {
    return json({ ok: false, error: "gateway-unauthorized" }, 401);
  }

  let body: Record<string, unknown>;
  try {
    const parsed = await request.json();
    body =
      typeof parsed === "object" && parsed !== null && !Array.isArray(parsed)
        ? (parsed as Record<string, unknown>)
        : {};
  } catch {
    return json({ ok: false, error: "invalid-json" }, 400);
  }

  const action = typeof body.action === "string" ? body.action : "";

  try {
    if (action === "status") return await gatewayStatus(access);
    if (action === "tool") return await gatewayTool(access, body);
    return json({ ok: false, error: "unknown-action" }, 400);
  } catch {
    return json({ ok: false, error: "gateway-internal-error" }, 500);
  }
});

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SERVICE_ROLE = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const REST = SUPABASE_URL + "/rest/v1";
const MAX_CLOCK_SKEW_MS = 120_000;
const SESSION_TTL_MS = 12 * 60 * 60_000;
const ONLINE_WINDOW_MS = 90_000;
const JOB_TIMEOUT_MS = 25_000;

const TOOLS: Record<string,{scopes:string[]}> = {
  "bridge.handshake": { scopes: ["terminal:open"] },
  "git.status": { scopes: ["git:read"] },
  "metrics.read": { scopes: ["metrics:read"] },
  "proc.list": { scopes: ["proc:list"] },
  "logs.read": { scopes: ["logs:read"] },
  "fs.list": { scopes: ["fs:read"] },
  "fs.read": { scopes: ["fs:read"] },
};

function json(data: unknown, status=200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {"content-type":"application/json","cache-control":"no-store"},
  });
}

async function db(path:string, init:RequestInit={}) {
  const headers = new Headers(init.headers);
  headers.set("apikey", SERVICE_ROLE);
  headers.set("authorization", "Bearer " + SERVICE_ROLE);
  headers.set("content-type", "application/json");
  if (!headers.has("prefer") && init.method && init.method !== "GET") {
    headers.set("prefer","return=representation");
  }
  const res = await fetch(REST + "/" + path, {...init, headers});
  const text = await res.text();
  let body:any = null;
  if (text) {
    try { body = JSON.parse(text); } catch { body = text; }
  }
  if (!res.ok) throw new Error("db:" + res.status + ":" + (typeof body==="string"?body.slice(0,300):JSON.stringify(body).slice(0,300)));
  return body;
}

function b64url(bytes:Uint8Array) {
  let s=""; for (const b of bytes) s+=String.fromCharCode(b);
  return btoa(s).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");
}
function b64urlDecode(input:string) {
  const n=input.replace(/-/g,"+").replace(/_/g,"/");
  const p=n+"=".repeat((4-n.length%4)%4);
  const raw=atob(p);
  return Uint8Array.from(raw,c=>c.charCodeAt(0));
}
function pemToDer(pem:string) {
  const body=pem.replace(/-----BEGIN [^-]+-----/g,"").replace(/-----END [^-]+-----/g,"").replace(/\s+/g,"");
  return Uint8Array.from(atob(body),c=>c.charCodeAt(0));
}
function derToPem(buf:ArrayBuffer,label:string) {
  const bytes=new Uint8Array(buf); let raw="";
  for(const b of bytes) raw+=String.fromCharCode(b);
  const body=btoa(raw).match(/.{1,64}/g)?.join("\n")??"";
  return `-----BEGIN ${label}-----\n${body}\n-----END ${label}-----\n`;
}
async function sha256Hex(value:string|Uint8Array) {
  const bytes=typeof value==="string"?new TextEncoder().encode(value):value;
  const dig=new Uint8Array(await crypto.subtle.digest("SHA-256",bytes));
  return [...dig].map(b=>b.toString(16).padStart(2,"0")).join("");
}
function randomToken(bytes=32) {
  const out=new Uint8Array(bytes); crypto.getRandomValues(out); return b64url(out);
}
function first<T=any>(v:any):T|null { return Array.isArray(v)&&v.length?v[0]:null; }

async function config() {
  const rows=await db("knoux_bridge_control_config?select=issuer_public_key,issuer_fingerprint,allowed_bridge_id,allowed_gateway_sa_email,allowed_gateway_audience&singleton=eq.true");
  const row=first(rows);
  if(!row) throw new Error("control-config-unavailable");
  return row;
}

async function ensureSigningKey() {
  let cfg=await config();
  let privRows=await db("rpc/knoux_bridge_get_signing_private_key",{method:"POST",body:"{}"});
  let privateKey=typeof privRows==="string"?privRows:privRows;
  if(cfg.issuer_public_key&&cfg.issuer_fingerprint&&privateKey) {
    return {publicKeyPem:cfg.issuer_public_key,privateKeyPem:privateKey,fingerprint:cfg.issuer_fingerprint};
  }
  if(cfg.issuer_public_key||cfg.issuer_fingerprint||privateKey) throw new Error("incomplete-signing-state");

  const pair=await crypto.subtle.generateKey({name:"Ed25519"},true,["sign","verify"]) as CryptoKeyPair;
  const spki=await crypto.subtle.exportKey("spki",pair.publicKey);
  const pkcs8=await crypto.subtle.exportKey("pkcs8",pair.privateKey);
  const publicKeyPem=derToPem(spki,"PUBLIC KEY");
  const privateKeyPem=derToPem(pkcs8,"PRIVATE KEY");
  const fingerprint=await sha256Hex(new Uint8Array(spki));

  await db("rpc/knoux_bridge_store_signing_key",{
    method:"POST",
    body:JSON.stringify({p_private_key:privateKeyPem,p_public_key:publicKeyPem,p_fingerprint:fingerprint}),
  });

  cfg=await config();
  privRows=await db("rpc/knoux_bridge_get_signing_private_key",{method:"POST",body:"{}"});
  privateKey=typeof privRows==="string"?privRows:privRows;
  if(!cfg.issuer_public_key||!cfg.issuer_fingerprint||!privateKey) throw new Error("signing-key-init-failed");
  return {publicKeyPem:cfg.issuer_public_key,privateKeyPem:privateKey,fingerprint:cfg.issuer_fingerprint};
}

async function verifyRegistration(body:any) {
  if(!body||typeof body!=="object"||typeof body.payload!=="string"||typeof body.signature!=="string") throw new Error("invalid-envelope");
  if(body.payload.length>64000||body.signature.length>1000) throw new Error("invalid-envelope");
  let p:any; try{p=JSON.parse(body.payload)}catch{throw new Error("invalid-payload")}
  for(const k of ["bridgeId","fingerprint","publicKey","nonce","timestamp","hostname","platform","arch","version"]){
    if(typeof p[k]!=="string") throw new Error("invalid-payload");
  }
  if(!p.capabilities||typeof p.capabilities!=="object") throw new Error("invalid-payload");
  const ts=Date.parse(p.timestamp);
  if(!Number.isFinite(ts)||Math.abs(Date.now()-ts)>MAX_CLOCK_SKEW_MS) throw new Error("stale-registration");
  if(!/^[0-9a-f]{64}$/.test(p.fingerprint)||p.bridgeId!==p.fingerprint.slice(0,16)) throw new Error("identity-mismatch");
  if(!/^[A-Za-z0-9_-]{16,128}$/.test(p.nonce)) throw new Error("invalid-nonce");
  const spki=pemToDer(p.publicKey);
  if(spki.length<32) throw new Error("invalid-public-key");
  if(await sha256Hex(spki.slice(spki.length-32))!==p.fingerprint) throw new Error("public-key-mismatch");
  const key=await crypto.subtle.importKey("spki",spki,{name:"Ed25519"},false,["verify"]);
  const ok=await crypto.subtle.verify("Ed25519",key,b64urlDecode(body.signature),new TextEncoder().encode(body.payload));
  if(!ok) throw new Error("invalid-signature");
  return p;
}

async function machineAuth(req:Request) {
  const m=/^Bearer\s+([A-Za-z0-9_-]{32,256})$/i.exec(req.headers.get("authorization")??"");
  if(!m) return null;
  const hash=await sha256Hex(m[1]);
  const sessions=await db("knoux_bridge_sessions?select=id,machine_id,owner_id,expires_at,revoked_at&token_hash=eq."+hash+"&limit=1");
  const s=first(sessions);
  if(!s||s.revoked_at||Date.parse(s.expires_at)<=Date.now()) return null;
  const machines=await db("knoux_bridge_machines?select=id,owner_id,bridge_id,fingerprint,status&id=eq."+s.machine_id+"&limit=1");
  const machine=first(machines);
  if(!machine||machine.status==="revoked"||machine.owner_id!==s.owner_id) return null;
  return {session:s,machine};
}

async function register(req:Request) {
  let body:any; try{body=await req.json()}catch{return json({error:"invalid-body"},400)}
  let p:any; try{p=await verifyRegistration(body)}catch(e){return json({error:e instanceof Error?e.message:"invalid-registration"},401)}
  const cfg=await config();
  if(cfg.allowed_bridge_id&&cfg.allowed_bridge_id!==p.bridgeId) return json({error:"bridge-not-allowed"},403);

  const existing=first(await db("knoux_bridge_machines?select=id,owner_id,bridge_id,fingerprint,public_key,status&bridge_id=eq."+p.bridgeId+"&limit=1"));
  let machine:any;
  if(existing){
    if(existing.fingerprint!==p.fingerprint||existing.public_key!==p.publicKey||existing.status==="revoked") return json({error:"machine-identity-rejected"},403);
    machine={id:existing.id,owner_id:existing.owner_id,bridge_id:existing.bridge_id};
    await db("knoux_bridge_machines?id=eq."+existing.id,{method:"PATCH",body:JSON.stringify({
      hostname:String(p.hostname).slice(0,255),platform:String(p.platform).slice(0,64),arch:String(p.arch).slice(0,64),
      bridge_version:String(p.version).slice(0,64),capabilities:p.capabilities,status:"online",
      last_seen_at:new Date().toISOString(),updated_at:new Date().toISOString()
    })});
  }else{
    const token=typeof p.enrollmentToken==="string"?p.enrollmentToken.trim():"";
    if(!/^[A-Za-z0-9_-]{20,128}$/.test(token)) return json({error:"enrollment-required"},403);
    const rows=await db("rpc/knoux_bridge_enroll_machine",{method:"POST",body:JSON.stringify({
      p_token_hash:await sha256Hex(token),p_bridge_id:p.bridgeId,p_fingerprint:p.fingerprint,p_public_key:p.publicKey,
      p_hostname:String(p.hostname).slice(0,255),p_platform:String(p.platform).slice(0,64),p_arch:String(p.arch).slice(0,64),
      p_bridge_version:String(p.version).slice(0,64),p_capabilities:p.capabilities
    })});
    const row=first(rows); if(!row) return json({error:"enrollment-invalid-or-expired"},403);
    const locked=await db("rpc/knoux_bridge_lock_allowed_bridge",{method:"POST",body:JSON.stringify({p_bridge_id:p.bridgeId})});
    if(locked!==true) return json({error:"bridge-lock-failed"},409);
    machine={id:row.id,owner_id:row.owner_id,bridge_id:row.bridge_id};
  }

  try{
    await db("knoux_bridge_registration_nonces",{method:"POST",body:JSON.stringify({
      nonce:p.nonce,machine_id:machine.id,expires_at:new Date(Date.now()+600000).toISOString()
    })});
  }catch{return json({error:"registration-replay"},409)}

  const now=new Date().toISOString();
  await db("knoux_bridge_sessions?machine_id=eq."+machine.id+"&revoked_at=is.null",{method:"PATCH",body:JSON.stringify({revoked_at:now})});
  const sessionToken=randomToken();
  const sessionRows=await db("knoux_bridge_sessions",{method:"POST",body:JSON.stringify({
    machine_id:machine.id,owner_id:machine.owner_id,token_hash:await sha256Hex(sessionToken),
    expires_at:new Date(Date.now()+SESSION_TTL_MS).toISOString(),last_seen_at:now
  })});
  const session=first(sessionRows); if(!session) return json({error:"session-create-failed"},503);
  const keys=await ensureSigningKey();
  await db("knoux_bridge_events",{method:"POST",body:JSON.stringify({
    owner_id:machine.owner_id,machine_id:machine.id,session_id:session.id,
    event:existing?"machine.reconnected":"machine.enrolled",
    detail:{bridgeId:p.bridgeId,hostname:p.hostname,platform:p.platform,version:p.version}
  })});
  return json({ok:true,machineId:machine.id,sessionId:session.id,sessionToken,
    expiresAt:new Date(Date.now()+SESSION_TTL_MS).toISOString(),heartbeatIntervalMs:30000,idlePollMs:10000,
    issuerPublicKey:keys.publicKeyPem,issuerFingerprint:keys.fingerprint});
}

async function heartbeat(req:Request){
  const a=await machineAuth(req); if(!a) return json({error:"machine-unauthorized"},401);
  let body:any={}; try{body=await req.json()}catch{}
  const now=new Date().toISOString();
  const upd:any={status:"online",last_seen_at:now,updated_at:now};
  if(typeof body.version==="string"&&body.version.length<=64) upd.bridge_version=body.version;
  if(body.capabilities&&typeof body.capabilities==="object") upd.capabilities=body.capabilities;
  await Promise.all([
    db("knoux_bridge_machines?id=eq."+a.machine.id,{method:"PATCH",body:JSON.stringify(upd)}),
    db("knoux_bridge_sessions?id=eq."+a.session.id,{method:"PATCH",body:JSON.stringify({last_seen_at:now})})
  ]);
  return json({ok:true,machineId:a.machine.id,serverTime:now,sessionExpiresAt:a.session.expires_at});
}

async function mintTicket(ownerId:string,bridgeId:string,jobId:string,scopes:string[]){
  const keys=await ensureSigningKey();
  const key=await crypto.subtle.importKey("pkcs8",pemToDer(keys.privateKeyPem),{name:"Ed25519"},false,["sign"]);
  const now=Math.floor(Date.now()/1000);
  const h=b64url(new TextEncoder().encode(JSON.stringify({alg:"EdDSA",typ:"KNX-TKT",kid:keys.fingerprint.slice(0,16)})));
  const c=b64url(new TextEncoder().encode(JSON.stringify({
    iss:"knoux-bff",aud:bridgeId,sub:ownerId,sid:"cloud-job-"+jobId,scope:scopes,
    jti:crypto.randomUUID(),iat:now,exp:now+60
  })));
  const input=h+"."+c;
  const sig=await crypto.subtle.sign("Ed25519",key,new TextEncoder().encode(input));
  return input+"."+b64url(new Uint8Array(sig));
}

async function poll(req:Request){
  const a=await machineAuth(req); if(!a) return json({error:"machine-unauthorized"},401);
  const now=new Date().toISOString();
  await Promise.all([
    db("knoux_bridge_machines?id=eq."+a.machine.id,{method:"PATCH",body:JSON.stringify({status:"online",last_seen_at:now,updated_at:now})}),
    db("knoux_bridge_sessions?id=eq."+a.session.id,{method:"PATCH",body:JSON.stringify({last_seen_at:now})})
  ]);
  const rows=await db("rpc/knoux_bridge_claim_job",{method:"POST",body:JSON.stringify({p_machine_id:a.machine.id,p_session_id:a.session.id})});
  const job=first(rows); if(!job) return new Response(null,{status:204});
  const spec=TOOLS[job.tool];
  if(!spec){
    await db("knoux_bridge_jobs?id=eq."+job.id,{method:"PATCH",body:JSON.stringify({status:"failed",completed_at:now,error:"Tool is not allowlisted."})});
    return json({error:"job-not-allowlisted"},409);
  }
  const bridgeTicket=await mintTicket(a.session.owner_id,a.machine.bridge_id,job.id,spec.scopes);
  await db("knoux_bridge_events",{method:"POST",body:JSON.stringify({
    owner_id:a.session.owner_id,machine_id:a.machine.id,session_id:a.session.id,job_id:job.id,event:"job.claimed",detail:{tool:job.tool}
  })});
  return json({ok:true,job:{id:job.id,tool:job.tool,args:job.args??{},expiresAt:job.expires_at},bridgeTicket});
}

async function result(req:Request){
  const a=await machineAuth(req); if(!a) return json({error:"machine-unauthorized"},401);
  let body:any; try{body=await req.json()}catch{return json({error:"invalid-body"},400)}
  const jobId=typeof body.jobId==="string"?body.jobId:"";
  if(!/^[0-9a-f-]{36}$/i.test(jobId)) return json({error:"invalid-job-id"},400);
  const job=first(await db("knoux_bridge_jobs?select=id,status&id=eq."+jobId+"&machine_id=eq."+a.machine.id+"&limit=1"));
  if(!job) return json({error:"job-not-found"},404);
  if(!["claimed","running"].includes(job.status)) return json({error:"job-not-claimable"},409);
  const ok=body.ok===true, completed=new Date().toISOString();
  const upd:any={status:ok?"succeeded":"failed",completed_at:completed,result:ok?(body.result??null):null,
    error:ok?null:(typeof body.error==="string"?body.error.slice(0,2000):"Local bridge failure"),
    duration_ms:Number.isFinite(body.durationMs)?Math.max(0,Math.min(Number(body.durationMs),86400000)):null};
  if(job.status==="claimed") upd.started_at=completed;
  await db("knoux_bridge_jobs?id=eq."+jobId,{method:"PATCH",body:JSON.stringify(upd)});
  await db("knoux_bridge_events",{method:"POST",body:JSON.stringify({
    owner_id:a.session.owner_id,machine_id:a.machine.id,session_id:a.session.id,job_id:jobId,
    event:ok?"job.succeeded":"job.failed",detail:{durationMs:upd.duration_ms}
  })});
  return json({ok:true});
}

async function googleGatewayAuth(req:Request){
  const cfg=await config();
  if(!cfg.allowed_gateway_sa_email||!cfg.allowed_gateway_audience) return null;
  const m=/^Bearer\s+(.+)$/.exec(req.headers.get("authorization")??""); if(!m) return null;
  const res=await fetch("https://oauth2.googleapis.com/tokeninfo?id_token="+encodeURIComponent(m[1]));
  if(!res.ok) return null;
  const c=await res.json();
  const iss=c.iss==="accounts.google.com"||c.iss==="https://accounts.google.com";
  const exp=Number(c.exp)*1000>Date.now();
  if(!iss||!exp||c.aud!==cfg.allowed_gateway_audience||c.email!==cfg.allowed_gateway_sa_email||String(c.email_verified)!=="true") return null;
  return cfg;
}

function validateArgs(tool:string,raw:any){
  const a=raw&&typeof raw==="object"&&!Array.isArray(raw)?raw:{};
  if(["bridge.handshake","git.status","metrics.read","proc.list"].includes(tool)){
    if(Object.keys(a).length) throw new Error("tool-does-not-accept-args"); return {};
  }
  if(tool==="logs.read"){
    const name=typeof a.name==="string"?a.name.trim():""; if(!/^[A-Za-z0-9._-]{1,64}$/.test(name)) throw new Error("invalid-process-name");
    return {name,since:Number.isInteger(a.since)?Math.max(0,Number(a.since)):0,limit:Number.isInteger(a.limit)?Math.max(1,Math.min(500,Number(a.limit))):200};
  }
  const path=typeof a.path==="string"?a.path.trim():""; if(!path||path.length>4096||path.includes("\0")) throw new Error("invalid-path");
  return {path};
}
async function selectedMachine(id:string){
  return first(await db("knoux_bridge_machines?select=id,owner_id,bridge_id,hostname,platform,arch,bridge_version,capabilities,status,last_seen_at,registered_at&bridge_id=eq."+id+"&limit=1"));
}
async function gatewayStatus(req:Request){
  const cfg=await googleGatewayAuth(req); if(!cfg) return json({error:"gateway-unauthorized"},401);
  if(!cfg.allowed_bridge_id) return json({ok:true,local_machine_connected:false,machine:null,reason:"no-enrolled-bridge"});
  const m=await selectedMachine(cfg.allowed_bridge_id); if(!m) return json({ok:true,local_machine_connected:false,machine:null,reason:"machine-not-found"});
  const age=Math.max(0,Date.now()-Date.parse(m.last_seen_at)), online=m.status!=="revoked"&&age<=ONLINE_WINDOW_MS;
  return json({ok:true,service:"knoux-store-control-plane",local_machine_connected:online,machine:{
    bridge_id:m.bridge_id,hostname:m.hostname,platform:m.platform,arch:m.arch,version:m.bridge_version,capabilities:m.capabilities,
    status:m.status==="revoked"?"revoked":online?"online":"offline",last_seen_at:m.last_seen_at,last_seen_age_ms:age,registered_at:m.registered_at
  },measured_at:new Date().toISOString()});
}
async function gatewayRun(req:Request){
  const cfg=await googleGatewayAuth(req); if(!cfg) return json({error:"gateway-unauthorized"},401);
  if(!cfg.allowed_bridge_id) return json({error:"no-enrolled-bridge"},409);
  let body:any; try{body=await req.json()}catch{return json({error:"invalid-body"},400)}
  const tool=typeof body.tool==="string"?body.tool:"", spec=TOOLS[tool]; if(!spec) return json({error:"tool-not-allowlisted"},400);
  let args:any; try{args=validateArgs(tool,body.args)}catch(e){return json({error:e instanceof Error?e.message:"invalid-args"},400)}
  const m=await selectedMachine(cfg.allowed_bridge_id); if(!m) return json({error:"machine-not-found"},404);
  if(m.status==="revoked"||Date.now()-Date.parse(m.last_seen_at)>ONLINE_WINDOW_MS) return json({error:"machine-offline"},409);
  const created=first(await db("knoux_bridge_jobs",{method:"POST",body:JSON.stringify({
    owner_id:m.owner_id,machine_id:m.id,tool,args,required_scopes:spec.scopes,mutating:false,
    idempotency_key:crypto.randomUUID(),expires_at:new Date(Date.now()+300000).toISOString()
  })}));
  if(!created) return json({error:"job-create-failed"},503);
  const deadline=Date.now()+JOB_TIMEOUT_MS;
  while(Date.now()<deadline){
    const j=first(await db("knoux_bridge_jobs?select=id,status,result,error,duration_ms,completed_at&id=eq."+created.id+"&limit=1"));
    if(j&&["succeeded","failed","cancelled","expired"].includes(j.status)){
      if(j.status==="succeeded") return json({ok:true,job_id:j.id,tool,result:j.result,duration_ms:j.duration_ms,completed_at:j.completed_at});
      return json({ok:false,job_id:j.id,tool,error:j.error??j.status},502);
    }
    await new Promise(r=>setTimeout(r,500));
  }
  return json({error:"job-timeout",job_id:created.id},504);
}

Deno.serve(async(req:Request)=>{
  if(req.method!=="POST") return json({error:"method-not-allowed"},405);
  const p=new URL(req.url).pathname;
  try{
    if(p.endsWith("/register")) return await register(req);
    if(p.endsWith("/heartbeat")) return await heartbeat(req);
    if(p.endsWith("/poll")) return await poll(req);
    if(p.endsWith("/result")) return await result(req);
    if(p.endsWith("/gateway/status")) return await gatewayStatus(req);
    if(p.endsWith("/gateway/run")) return await gatewayRun(req);
    return json({error:"not-found"},404);
  }catch(e){
    console.error("[knoux-store-bridge-control]",e instanceof Error?e.message:String(e));
    return json({error:"internal-error"},500);
  }
});

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2";

type Json = Record<string, unknown>;
type RpcRequest = { jsonrpc?: string; id?: unknown; method?: string; params?: Json };

const ONLINE_WINDOW_MS = 90_000;
const JOB_WAIT_MS = 25_000;
const JOB_POLL_MS = 400;

const TOOL_MAP: Record<string, { local: string; description: string; inputSchema: Json }> = {
  gateway_status: {
    local: "",
    description: "Return measured KNOuX Store gateway and Windows bridge connectivity.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false },
  },
  machine_git_status: {
    local: "git.status",
    description: "Read the real Git status of the KNOuX Store workspace on the enrolled Windows machine.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false },
  },
  machine_metrics: {
    local: "metrics.read",
    description: "Read measured machine and bridge metrics from the enrolled Windows machine.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false },
  },
  machine_processes: {
    local: "proc.list",
    description: "List supervised KNOuX Store processes on the enrolled Windows machine.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false },
  },
  machine_list_files: {
    local: "fs.list",
    description: "List files under the configured KNOuX Store bridge root.",
    inputSchema: {
      type: "object",
      properties: { path: { type: "string", description: "Root-relative path." } },
      required: ["path"],
      additionalProperties: false,
    },
  },
  machine_read_file: {
    local: "fs.read",
    description: "Read one file under the configured KNOuX Store bridge root.",
    inputSchema: {
      type: "object",
      properties: { path: { type: "string", description: "Root-relative file path." } },
      required: ["path"],
      additionalProperties: false,
    },
  },
  machine_logs: {
    local: "logs.read",
    description: "Read bounded logs for a supervised KNOuX Store process.",
    inputSchema: {
      type: "object",
      properties: {
        name: { type: "string" },
        since: { type: "integer", minimum: 0, default: 0 },
        limit: { type: "integer", minimum: 1, maximum: 500, default: 200 },
      },
      required: ["name"],
      additionalProperties: false,
    },
  },
};

const LOCAL_TOOL_SCOPES: Record<string, string[]> = {
  "git.status": ["git:read"],
  "metrics.read": ["metrics:read"],
  "proc.list": ["proc:list"],
  "logs.read": ["logs:read"],
  "fs.list": ["fs:read"],
  "fs.read": ["fs:read"],
};

function serviceKey(): string {
  const modern = Deno.env.get("SUPABASE_SECRET_KEYS");
  if (modern) {
    try {
      const parsed = JSON.parse(modern) as Record<string, string>;
      if (parsed.default) return parsed.default;
    } catch {}
  }
  const legacy = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!legacy) throw new Error("service-key-unavailable");
  return legacy;
}

const db = createClient(
  Deno.env.get("SUPABASE_URL")!,
  serviceKey(),
  { auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false } },
);

function headers(contentType = "application/json; charset=utf-8"): HeadersInit {
  return {
    "content-type": contentType,
    "cache-control": "no-store",
    "x-content-type-options": "nosniff",
  };
}

function rpcResponse(id: unknown, result: unknown): Response {
  return new Response(JSON.stringify({ jsonrpc: "2.0", id, result }), {
    status: 200,
    headers: headers(),
  });
}

function rpcError(id: unknown, code: number, message: string): Response {
  return new Response(JSON.stringify({
    jsonrpc: "2.0",
    id: id ?? null,
    error: { code, message },
  }), { status: 200, headers: headers() });
}

function bearer(req: Request): string {
  const raw = req.headers.get("authorization") ?? "";
  const match = /^Bearer\s+([A-Za-z0-9_-]{20,512})$/i.exec(raw);
  return match?.[1] ?? "";
}

function toHex(bytes: Uint8Array): string {
  return Array.from(bytes, (value) => value.toString(16).padStart(2, "0")).join("");
}

async function sha256Hex(value: string): Promise<string> {
  return toHex(new Uint8Array(
    await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value)),
  ));
}

async function authenticate(req: Request) {
  const token = bearer(req);
  if (!token) return null;
  const tokenHash = await sha256Hex(token);

  const { data } = await db
    .from("knoux_bridge_gateway_tokens")
    .select("id,name,bridge_id,active,expires_at")
    .eq("token_hash", tokenHash)
    .eq("active", true)
    .maybeSingle();

  if (!data) return null;
  if (data.expires_at && Date.parse(data.expires_at) <= Date.now()) return null;

  await db
    .from("knoux_bridge_gateway_tokens")
    .update({ last_used_at: new Date().toISOString() })
    .eq("id", data.id);

  return data;
}

async function measuredStatus(bridgeId: string): Promise<Json> {
  const { data: machine } = await db
    .from("knoux_bridge_machines")
    .select("id,bridge_id,hostname,platform,arch,bridge_version,capabilities,status,last_seen_at,registered_at")
    .eq("bridge_id", bridgeId)
    .maybeSingle();

  if (!machine) {
    return {
      ok: true,
      service: "knoux-store-mcp",
      local_machine_connected: false,
      machine: null,
      measuredAt: new Date().toISOString(),
    };
  }

  const ageMs = Math.max(0, Date.now() - Date.parse(machine.last_seen_at));
  const online = machine.status !== "revoked" && ageMs <= ONLINE_WINDOW_MS;

  return {
    ok: true,
    service: "knoux-store-mcp",
    local_machine_connected: online,
    machine: {
      id: machine.id,
      bridgeId: machine.bridge_id,
      hostname: machine.hostname,
      platform: machine.platform,
      arch: machine.arch,
      version: machine.bridge_version,
      capabilities: machine.capabilities,
      status: machine.status === "revoked" ? "revoked" : (online ? "online" : "offline"),
      lastSeenAt: machine.last_seen_at,
      lastSeenAgeMs: ageMs,
      registeredAt: machine.registered_at,
    },
    measuredAt: new Date().toISOString(),
  };
}

function validateToolArgs(localTool: string, raw: unknown): { ok: true; args: Json } | { ok: false; error: string } {
  const args = typeof raw === "object" && raw !== null && !Array.isArray(raw)
    ? raw as Json
    : {};

  if (["git.status", "metrics.read", "proc.list"].includes(localTool)) {
    return Object.keys(args).length === 0
      ? { ok: true, args: {} }
      : { ok: false, error: "unexpected-arguments" };
  }

  if (localTool === "logs.read") {
    const name = typeof args.name === "string" ? args.name.trim() : "";
    if (!/^[A-Za-z0-9._-]{1,64}$/.test(name)) {
      return { ok: false, error: "invalid-process-name" };
    }
    const since = Number.isInteger(args.since) && Number(args.since) >= 0 ? Number(args.since) : 0;
    const limit = Number.isInteger(args.limit) ? Math.max(1, Math.min(500, Number(args.limit))) : 200;
    return { ok: true, args: { name, since, limit } };
  }

  if (localTool === "fs.list" || localTool === "fs.read") {
    const path = typeof args.path === "string" ? args.path.trim() : "";
    if (!path || path.length > 4096 || path.includes("\0")) {
      return { ok: false, error: "invalid-path" };
    }
    return { ok: true, args: { path } };
  }

  return { ok: false, error: "tool-not-allowlisted" };
}

async function runTool(bridgeId: string, localTool: string, rawArgs: unknown): Promise<Json> {
  const validated = validateToolArgs(localTool, rawArgs);
  if (!validated.ok) {
    return { ok: false, error: validated.error };
  }

  const { data: machine } = await db
    .from("knoux_bridge_machines")
    .select("id,owner_id,bridge_id,status,last_seen_at")
    .eq("bridge_id", bridgeId)
    .maybeSingle();

  if (!machine) return { ok: false, error: "machine-not-found" };

  const ageMs = Date.now() - Date.parse(machine.last_seen_at);
  if (machine.status === "revoked" || ageMs > ONLINE_WINDOW_MS) {
    return { ok: false, error: "machine-offline" };
  }

  const { data: job, error } = await db
    .from("knoux_bridge_jobs")
    .insert({
      owner_id: machine.owner_id,
      machine_id: machine.id,
      tool: localTool,
      args: validated.args,
      required_scopes: LOCAL_TOOL_SCOPES[localTool] ?? [],
      mutating: false,
      idempotency_key: crypto.randomUUID(),
      expires_at: new Date(Date.now() + 5 * 60_000).toISOString(),
    })
    .select("id")
    .single();

  if (error || !job) return { ok: false, error: "job-create-failed" };

  const deadline = Date.now() + JOB_WAIT_MS;
  while (Date.now() < deadline) {
    const { data: current } = await db
      .from("knoux_bridge_jobs")
      .select("id,status,result,error,duration_ms,completed_at")
      .eq("id", job.id)
      .maybeSingle();

    if (current && ["succeeded", "failed", "cancelled", "expired"].includes(current.status)) {
      return {
        ok: current.status === "succeeded",
        jobId: current.id,
        tool: localTool,
        status: current.status,
        result: current.result,
        error: current.error,
        durationMs: current.duration_ms,
        completedAt: current.completed_at,
      };
    }
    await new Promise((resolve) => setTimeout(resolve, JOB_POLL_MS));
  }

  return { ok: false, error: "job-timeout", jobId: job.id, tool: localTool };
}

function toolList() {
  return Object.entries(TOOL_MAP).map(([name, spec]) => ({
    name,
    description: spec.description,
    inputSchema: spec.inputSchema,
  }));
}

async function callTool(
  gateway: { bridge_id: string },
  params: Json,
): Promise<Json> {
  const name = typeof params.name === "string" ? params.name : "";
  const spec = TOOL_MAP[name];
  if (!spec) {
    return {
      content: [{ type: "text", text: JSON.stringify({ ok: false, error: "unknown-tool" }) }],
      isError: true,
    };
  }

  const result = name === "gateway_status"
    ? await measuredStatus(gateway.bridge_id)
    : await runTool(gateway.bridge_id, spec.local, params.arguments ?? {});

  return {
    content: [{ type: "text", text: JSON.stringify(result) }],
    structuredContent: result,
    isError: result.ok !== true,
  };
}

Deno.serve(async (req: Request) => {
  if (req.method === "GET") {
    return new Response("POST JSON-RPC requests to this MCP endpoint.", {
      status: 405,
      headers: { ...headers("text/plain; charset=utf-8"), allow: "POST" },
    });
  }

  if (req.method !== "POST") {
    return new Response(null, { status: 405, headers: { allow: "POST" } });
  }

  const gateway = await authenticate(req);
  if (!gateway) {
    return new Response(JSON.stringify({ error: "unauthorized" }), {
      status: 401,
      headers: headers(),
    });
  }

  let rpc: RpcRequest;
  try {
    rpc = await req.json() as RpcRequest;
  } catch {
    return rpcError(null, -32700, "Parse error");
  }

  if (rpc.jsonrpc !== "2.0" || typeof rpc.method !== "string") {
    return rpcError(rpc.id, -32600, "Invalid Request");
  }

  if (rpc.id === undefined) {
    return new Response(null, { status: 202, headers: { "cache-control": "no-store" } });
  }

  switch (rpc.method) {
    case "initialize": {
      const requested = typeof rpc.params?.protocolVersion === "string"
        ? rpc.params.protocolVersion
        : "2025-03-26";
      return rpcResponse(rpc.id, {
        protocolVersion: requested,
        capabilities: { tools: { listChanged: false } },
        serverInfo: { name: "KNOuX Store MCP Gateway", version: "1.0.0" },
        instructions: "Read-only access to the enrolled KNOuX Store Windows bridge.",
      });
    }
    case "ping":
      return rpcResponse(rpc.id, {});
    case "tools/list":
      return rpcResponse(rpc.id, { tools: toolList() });
    case "tools/call":
      return rpcResponse(rpc.id, await callTool(gateway, rpc.params ?? {}));
    default:
      return rpcError(rpc.id, -32601, "Method not found");
  }
});
